require_once __DIR__.'/auth.php';require_user();require_once __DIR__.'/navbar.php';$user=current_user();if(($user['user_level']??'')!=='admin'){http_response_code(403);exit('เฉพาะผู้ดูแลระบบเท่านั้น');}
$error='';$flash=$_SESSION['member_crud_flash']??null;unset($_SESSION['member_crud_flash']);function members_redirect(){header('Location: '.url_for('members.php'));exit;}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{if(!verify_csrf($_POST['csrf_token']??''))throw new RuntimeException('แบบฟอร์มหมดอายุ กรุณาลองใหม่');$action=$_POST['action']??'';$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if($action==='delete'){if(!$id)throw new RuntimeException('ไม่พบสมาชิก');db()->prepare('DELETE FROM tbl_member WHERE mem_id=:id')->execute(['id'=>$id]);$_SESSION['member_crud_flash']=['type'=>'success','message'=>'ลบสมาชิกเรียบร้อย'];members_redirect();}if(!in_array($action,['create','update'],true))throw new RuntimeException('คำสั่งไม่ถูกต้อง');$data=['group'=>trim($_POST['group']??''),'number'=>trim($_POST['number']??''),'fullname'=>trim($_POST['fullname']??''),'birthtext'=>trim($_POST['birthtext']??''),'class'=>($_POST['class']??'')==='farmer'?'farmer':'member','personcode'=>trim($_POST['personcode']??''),'saveby'=>$user['user_fullname'],'savedate'=>date('Y-m-d')];if($data['number']===''||$data['fullname']==='')throw new RuntimeException('กรุณาระบุเลขสมาชิกและชื่อ-สกุล');if(mb_strlen($data['birthtext'])>8)throw new RuntimeException('ข้อมูลวันเกิดต้องไม่เกิน 8 ตัวอักษร');if($action==='create'){$sql='INSERT INTO tbl_member(mem_group,mem_number,mem_fullname,mem_birthtext,mem_class,mem_personcode,mem_saveby,mem_savedate) VALUES(:group,:number,:fullname,:birthtext,:class,:personcode,:saveby,:savedate)';$message='เพิ่มสมาชิกเรียบร้อย';}else{if(!$id)throw new RuntimeException('ไม่พบสมาชิก');$data['id']=$id;$sql='UPDATE tbl_member SET mem_group=:group,mem_number=:number,mem_fullname=:fullname,mem_birthtext=:birthtext,mem_class=:class,mem_personcode=:personcode,mem_saveby=:saveby,mem_savedate=:savedate WHERE mem_id=:id';$message='แก้ไขสมาชิกเรียบร้อย';}db()->prepare($sql)->execute($data);$_SESSION['member_crud_flash']=['type'=>'success','message'=>$message];members_redirect();}catch(Throwable $e){$error=$e instanceof PDOException?db_friendly_error($e):$e->getMessage();}
$edit=null;if(isset($_GET['edit'])&&($editId=filter_var($_GET['edit'],FILTER_VALIDATE_INT))){$s=db()->prepare('SELECT * FROM tbl_member WHERE mem_id=:id');$s->execute(['id'=>$editId]);$edit=$s->fetch()?:null;}$q=trim($_GET['q']??'');$page=max(1,(int)($_GET['page']??1));$perPage=25;$where='';$params=[];if($q!==''){$where=' WHERE mem_fullname LIKE :q OR mem_number LIKE :q OR mem_group LIKE :q OR mem_personcode LIKE :q';$params['q']='%'.$q.'%';}$s=db()->prepare('SELECT COUNT(*) FROM tbl_member'.$where);$s->execute($params);$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$offset=($page-1)*$perPage;$s=db()->prepare('SELECT * FROM tbl_member'.$where.' ORDER BY mem_id DESC LIMIT '.$perPage.' OFFSET '.$offset);$s->execute($params);$members=$s->fetchAll();
?>
<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>จัดการสมาชิก</title><link href="https://fonts.googleapis.com/css2?family=Sarabun:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="<?php echo h(navbar_url('navbar.css'));?>" rel="stylesheet"><link href="<?php echo h(url_for('admin-crud.css'));?>" rel="stylesheet"></head><body><?php render_topbar();?><main class="admin-shell"><section class="admin-hero"><div><h1><i class="bi bi-people-fill me-2"></i>จัดการสมาชิก</h1><p>เพิ่ม แก้ไข ค้นหา และจัดการข้อมูลสมาชิกสหกรณ์</p></div><span class="hero-count"><?php echo number_format($total);?> ราย</span></section><?php if($flash):?><div class="alert alert-<?php echo h($flash['type']);?>"><?php echo h($flash['message']);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo h($error);?></div><?php endif;?><div class="crud-grid"><section class="crud-card sticky"><div class="crud-head"><h2><?php echo $edit?'แก้ไขสมาชิก':'เพิ่มสมาชิก';?></h2></div><form class="crud-body" method="post"><input type="hidden" name="csrf_token" value="<?php echo h(csrf_token());?>"><input type="hidden" name="action" value="<?php echo $edit?'update':'create';?>"><?php if($edit):?><input type="hidden" name="id" value="<?php echo (int)$edit['mem_id'];?>"><?php endif;?><div class="row g-2 mb-3"><div class="col"><label class="form-label">กลุ่ม</label><input class="form-control" name="group" value="<?php echo h($edit['mem_group']??'');?>"></div><div class="col"><label class="form-label">เลขสมาชิก</label><input class="form-control" name="number" value="<?php echo h($edit['mem_number']??'');?>" required></div></div><div class="mb-3"><label class="form-label">ชื่อ-สกุล</label><input class="form-control" name="fullname" value="<?php echo h($edit['mem_fullname']??'');?>" required></div><div class="row g-2 mb-3"><div class="col"><label class="form-label">วันเกิด/ข้อความ</label><input class="form-control" name="birthtext" maxlength="8" value="<?php echo h($edit['mem_birthtext']??'');?>"></div><div class="col"><label class="form-label">ประเภท</label><select class="form-select" name="class"><option value="member" <?php echo ($edit['mem_class']??'member')==='member'?'selected':'';?>>สมาชิก</option><option value="farmer" <?php echo ($edit['mem_class']??'')==='farmer'?'selected':'';?>>เกษตรกร</option></select></div></div><div class="mb-4"><label class="form-label">รหัสบุคคล</label><input class="form-control" name="personcode" value="<?php echo h($edit['mem_personcode']??'');?>"></div><div class="d-grid gap-2"><button class="btn btn-purple"><i class="bi bi-floppy me-1"></i>บันทึก</button><?php if($edit):?><a class="btn btn-light" href="<?php echo h(url_for('members.php'));?>">ยกเลิก</a><?php endif;?></div></form></section><section class="crud-card"><div class="toolbar"><strong>รายชื่อสมาชิก</strong><form class="search-form"><input class="form-control" name="q" value="<?php echo h($q);?>" placeholder="ชื่อ เลขสมาชิก กลุ่ม"><button class="btn btn-dark"><i class="bi bi-search"></i></button></form></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>กลุ่ม</th><th>เลขสมาชิก</th><th>ชื่อ-สกุล</th><th>ประเภท</th><th>รหัสบุคคล</th><th>ผู้บันทึก</th><th class="text-end">จัดการ</th></tr></thead><tbody><?php foreach($members as $row):?><tr><td><?php echo h($row['mem_group']);?></td><td class="fw-bold"><?php echo h($row['mem_number']);?></td><td><?php echo h($row['mem_fullname']);?></td><td><span class="status-badge <?php echo $row['mem_class']==='member'?'status-active':'level-user';?>"><?php echo $row['mem_class']==='member'?'สมาชิก':'เกษตรกร';?></span></td><td><?php echo h($row['mem_personcode']);?></td><td><small><?php echo h($row['mem_saveby']);?><br><?php echo h($row['mem_savedate']);?></small></td><td><div class="row-actions"><a class="btn btn-sm btn-outline-primary" href="?edit=<?php echo (int)$row['mem_id'];?>"><i class="bi bi-pencil"></i></a><form method="post" onsubmit="return confirm('ยืนยันการลบสมาชิกนี้?')"><input type="hidden" name="csrf_token" value="<?php echo h(csrf_token());?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?php echo (int)$row['mem_id'];?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$members):?><tr><td colspan="7" class="empty">ไม่พบข้อมูลสมาชิก</td></tr><?php endif;?></tbody></table></div><ul class="pagination"><?php if($page>1):?><li class="page-item"><a class="page-link" href="?<?php echo http_build_query(['q'=>$q,'page'=>$page-1]);?>">ก่อนหน้า</a></li><?php endif;?><?php for($p=max(1,$page-2);$p<=min($pages,$page+2);$p++):?><li class="page-item <?php echo $p===$page?'active':'';?>"><a class="page-link" href="?<?php echo http_build_query(['q'=>$q,'page'=>$p]);?>"><?php echo $p;?></a></li><?php endfor;?><?php if($page<$pages):?><li class="page-item"><a class="page-link" href="?<?php echo http_build_query(['q'=>$q,'page'=>$page+1]);?>">ถัดไป</a></li><?php endif;?></ul></section></div></main></body></html>
